# RGB-derived: docs/deposit_coin/applied_values.json (rgb_derived_values).
# RGB updates generated by --run-geometry-fitting.
# Evidence: docs/deposit_coin/geometry_fit.json
import itertools
import numpy as np

def working_estimates():
    """RGB scene estimates and separately chosen pickup settings, in metres."""
    # Radius/thickness uncertainty is 0.0007 m each (rim/edge selection);
    # holder extent uncertainty is [0.0010, 0.0008, 0.0020] m.
    return {
        'coin': {'radius_m': 0.013, 'thickness_m': 0.0017},
        'holder': {
            'holder_dimensions_m': [0.0316, 0.0102, 0.0185],
            'holder_top_above_table_m': 0.0185,
            'finger_distal_from_hand_m': 0.158,
            'tcp_from_hand_m': 0.145,
            'fingertip_beyond_tcp_m': 0.0126,
            'open_finger_bounds_hand': [
                [0.0716, -0.0818, -0.0306],
                [0.158, 0.0818, 0.0304],
            ],
        },
        'pickup': {
            'fingertip_above_rgb_center_m': 0.00265,
            'minimum_target_holder_clearance_m': 0.0014,
            'depth_tolerance_m': 0.00025,
        },
    }

def calibration():
    return working_estimates()['holder']

def finger_bottom(hand_position, hand_rotation, shape=None):
    """Conservative minimum world z, including full-open finger travel."""
    shape = shape or calibration()
    lo, hi = np.asarray(shape['open_finger_bounds_hand'])
    corners = np.array(list(itertools.product(*zip(lo, hi))))
    return float((corners @ np.asarray(hand_rotation).T + hand_position)[:, 2].min())

def grasp_plan(coin, table_z, shape=None):
    shape = shape or calibration()
    holder_top = float(table_z + shape['holder_top_above_table_m'])
    result = dict(accepted=False, holder_top_z=holder_top, holder_dimensions_m=shape['holder_dimensions_m'])
    if not coin.get('grasp_accepted', coin.get('accepted')):
        return dict(result, reason='A usable resting-coin RGB grasp pose is required.')
    center = np.asarray(coin['center_xyz'], float)
    normal = np.asarray(coin['normal_xyz'], float)
    radius, thickness = (float(coin['radius_m']), float(coin['thickness_m']))
    if center.shape != (3,) or normal.shape != (3,) or (not np.isfinite(np.r_[center, normal, radius, thickness, table_z]).all()) or (abs(np.linalg.norm(normal) - 1.0) > 0.01) or (radius <= 0) or (thickness <= 0):
        return dict(result, reason='Invalid coin geometry.')
    if coin.get('support') == 'table':
        tip = float(table_z + 0.001)
        return dict(result, accepted=True, holder_top_z=float(table_z), support='table', pitch_deg=90.0, roll_deg=0.0, yaw_deg=float(coin['pickup_yaw_deg']), tcp_xyz=[float(center[0]), float(center[1]), tip + shape['fingertip_beyond_tcp_m']], fingertip_target_z=tip, holder_clearance_m=0.001, minimum_measured_clearance_m=0.0002, depth_tolerance_m=0.00025, pregrasp_z=float(table_z + 0.09), opening_gap_m=2 * radius + 0.008, coin_upper_z=float(center[2] + thickness / 2), note='Trial edge pinch of the flat coin at its current visual position. Use a diameter-wide opening, then close and lift slowly; correct lateral alignment on misses.')
    if abs(normal[2]) > np.sin(np.radians(10)):
        return dict(result, reason='The coin is no longer upright in its holder.')
    upper_z = float(center[2] + radius * np.sqrt(max(0.0, 1 - normal[2] ** 2)) + thickness * abs(normal[2]) / 2)
    reference = working_estimates()['pickup']
    fingertip_z = max(float(center[2] + reference['fingertip_above_rgb_center_m']), holder_top + reference['minimum_target_holder_clearance_m'])
    if upper_z - fingertip_z < 0.004 or center[2] > holder_top + 0.01:
        return dict(result, reason='The measured coin does not have a usable exposed grasp band.')
    horizontal_normal = normal.copy()
    horizontal_normal[2] = 0
    horizontal_normal /= np.linalg.norm(horizontal_normal)
    cosine = abs(float(normal @ horizontal_normal))
    width = 2 * radius * np.sqrt(max(0.0, 1 - cosine * cosine)) + thickness * cosine
    tcp_z = fingertip_z + shape['fingertip_beyond_tcp_m']
    return dict(result, accepted=True, pitch_deg=90.0, roll_deg=0.0, yaw_deg=float(np.degrees(np.arctan2(normal[1], normal[0]))), tcp_xyz=[float(center[0]), float(center[1]), float(tcp_z)], fingertip_target_z=fingertip_z, holder_clearance_m=fingertip_z - holder_top, fingertip_above_coin_center_m=fingertip_z - float(center[2]), depth_tolerance_m=reference['depth_tolerance_m'], minimum_measured_clearance_m=0.001, coin_upper_z=upper_z, exposed_overlap_m=upper_z - fingertip_z, pregrasp_z=max(upper_z + 0.08, tcp_z + 0.08), opening_gap_m=max(0.011, width + 0.008), note='Orient vertically while clear, align above the coin, then descend at fixed x/y and orientation. Use the calibrated coin-relative height; do not lower below this target to chase a deeper pinch.')
